#include <stdio.h>

int main(void) {
    int a[] = {2, 4, 8, 12, 16};            // size deduced: 5
    size_t n = sizeof a / sizeof a[0];      // 20 / 4 = 5

    for (size_t i = 0; i < n; i++)          // forward traversal
        printf("%d ", a[i]);
    printf("\n");

    for (size_t i = n; i-- > 0; )           // reverse, safe for unsigned i
        printf("%d ", a[i]);
    printf("\n");

    a[0] = 1;                               // update in place
    int sum = 0;
    for (size_t i = 0; i < n; i++) sum += a[i];
    printf("sum=%d\n", sum);                // 1+4+8+12+16 = 41
    return 0;
}

void scale(int *a, size_t n, int k) {
